const input = $input.first().json;
const body = input.body || input;
const curriculum = body.curriculum || {};
const modules = curriculum.modules || body.modules || [];
const courseTitle = curriculum.course?.title || body.course_title || '';
const level = curriculum.course?.level || body.level || 'debutant';
const audience = curriculum.course?.target_audience || body.target_audience || '';

// Flatten all lessons for batch processing
const lessons = [];
let prevSummary = '';

for (const mod of modules) {
  for (const lesson of (mod.lessons || [])) {
    lessons.push({
      course_title: courseTitle,
      level,
      target_audience: audience,
      module_title: mod.title,
      module_number: mod.module_number,
      total_modules: modules.length,
      lesson_title: lesson.title,
      lesson_number: lesson.lesson_number,
      total_lessons_in_module: (mod.lessons || []).length,
      lesson_type: lesson.type,
      duration_minutes: lesson.duration_minutes,
      bloom_level: lesson.bloom_level,
      content_brief: lesson.content_brief,
      key_concepts: lesson.key_concepts || [],
      local_example: lesson.local_example || '',
      media_needed: lesson.media_needed || {},
      teaching_method: lesson.teaching_method || 'expositive'
    });
  }
}

return lessons.map(l => ({ json: l }));

const response = $input.first().json;
const lessonMeta = $('Batch — Par leçon').first().json;

let lessonContent;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  lessonContent = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing leçon: ' + e.message);
}

const lesson = lessonContent.lesson || {};

// Build n8n-compatible Lesson object matching src/types/index.ts
const lessonDoc = {
  id: crypto.randomUUID(),
  title: lesson.title || lessonMeta.lesson_title,
  type: lessonMeta.lesson_type || 'text',
  duration: `${lesson.reading_time_minutes || lessonMeta.duration_minutes} min`,
  content: lesson.content_html || '',
  order: lessonMeta.lesson_number,
  isFree: lessonMeta.lesson_number === 1 && lessonMeta.module_number === 1,
  // Extra metadata for assembly
  module_number: lessonMeta.module_number,
  module_title: lessonMeta.module_title,
  course_title: lessonMeta.course_title,
  media_prompts: lesson.media_prompts || [],
  key_points: lesson.key_points || [],
  vocabulary: lesson.vocabulary || []
};

return [{ json: lessonDoc }];
